async function decompressResponse(res: Response): Promise<string> {
  const decompressedStream = res.body!.pipeThrough(new DecompressionStream('gzip'))
  const decompressedResponse = new Response(decompressedStream)
  return await decompressedResponse.text()
}

async function decompressBrotliResponse(res: Response): Promise<string> {
  // Try native DecompressionStream first (Cloudflare Workers, Deno, Bun, Node 22+).
  // Fall back to node:zlib for older Node versions.
  try {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const ds = new DecompressionStream('br' as any)
    return await new Response(res.body!.pipeThrough(ds)).text()
  } catch {
    // fall through
  }
  const zlibMod = await import('node:zlib')
  const streamMod = await import('node:stream')
  const brotli = zlibMod.createBrotliDecompress()
  const pair = {
    readable: streamMod.Readable.toWeb(brotli) as ReadableStream<Uint8Array>,
    writable: streamMod.Writable.toWeb(brotli) as WritableStream<Uint8Array>,
  }
  return await new Response(res.body!.pipeThrough(pair)).text()
}

