  describe('Brotli', () => {
    const buildApp = () => {
      const app = new Hono()
      app.use('*', compress())
      app.get('/large', (c) => {
        c.header('Content-Type', 'text/plain')
        c.header('Content-Length', '1024')
        return c.text('a'.repeat(1024))
      })
      app.get('/large-json', (c) => {
        c.header('Content-Type', 'application/json')
        c.header('Content-Length', '1024')
        return c.json({ data: 'a'.repeat(1024), message: 'Large JSON' })
      })
      app.get('/small', (c) => {
        c.header('Content-Type', 'text/plain')
        c.header('Content-Length', '5')
        return c.text('small')
      })
      app.get('/strong-etag', (c) => {
        c.header('Content-Type', 'text/plain')
        c.header('Content-Length', '1024')
        c.header('ETag', '"strong-etag"')
        return c.text('a'.repeat(1024))
      })
      app.get('/jpeg-image', (c) => {
        c.header('Content-Type', 'image/jpeg')
        c.header('Content-Length', '1024')
        return c.body(new Uint8Array(1024))
      })
      return app
    }

    it('should select brotli when Accept-Encoding includes br', async () => {
      const app = buildApp()
      const res = await app.request('/large', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(res.headers.get('Content-Encoding')).toBe('br')
    })

    it('should round-trip data through brotli compression', async () => {
      const app = buildApp()
      const res = await app.request('/large-json', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(res.headers.get('Content-Encoding')).toBe('br')
      expect(res.headers.get('Content-Length')).toBeNull()
      const text = await decompressBrotliResponse(res)
      const json = JSON.parse(text)
      expect(json.data.length).toBe(1024)
      expect(json.message).toBe('Large JSON')
    })

    it('should respect threshold with brotli', async () => {
      const app = buildApp()
      const res = await app.request('/small', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(res.headers.get('Content-Encoding')).toBeNull()
    })

    it('should convert strong ETag to weak ETag when brotli-compressing', async () => {
      const app = buildApp()
      const res = await app.request('/strong-etag', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(res.headers.get('Content-Encoding')).toBe('br')
      expect(res.headers.get('ETag')).toBe('W/"strong-etag"')
    })

    it('should not compress non-compressible content types with brotli', async () => {
      const app = buildApp()
      const res = await app.request('/jpeg-image', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(res.headers.get('Content-Encoding')).toBeNull()
    })

    it('should honor contentTypeFilter with brotli', async () => {
      const app = new Hono()
      app.use('*', compress({ contentTypeFilter: /^application\/json/, threshold: 0 }))
      app.get('/json', (c) => c.json({ data: 'a'.repeat(1024) }))
      app.get('/text', (c) => c.text('a'.repeat(1024)))

      const jsonRes = await app.request('/json', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(jsonRes.headers.get('Content-Encoding')).toBe('br')

      const textRes = await app.request('/text', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(textRes.headers.get('Content-Encoding')).toBeNull()
    })

    it('should honor encoding: "br" option', async () => {
      const app = new Hono()
      app.use('*', compress({ encoding: 'br' }))
      app.get('/large', (c) => {
        c.header('Content-Type', 'text/plain')
        c.header('Content-Length', '1024')
        return c.text('a'.repeat(1024))
      })

      const accepted = await app.request('/large', {
        headers: { 'Accept-Encoding': 'br' },
      })
